3	import * as React from "react";
4	import { CircleCheck, Ban } from "lucide-react";
5	import { DataTable, type Column } from "@/components/ui/DataTable";
6	import { StatusBadge } from "@/components/ui/StatusBadge";
7	import { SuspendUserButton } from "@/components/admin/SuspendUserButton";
